SELECT * FROM (SELECT CASE WHEN balance >= 67000 THEN 'high' WHEN balance >= 32000 THEN 'mid' ELSE 'low' END AS balance_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(account_type))) AS account_type_values, ROUND((100 * SUM(CASE WHEN account_type = 'SAVINGS' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_savings FROM accounts GROUP BY CASE WHEN balance >= 67000 THEN 'high' WHEN balance >= 32000 THEN 'mid' ELSE 'low' END) AS s WHERE pct_savings < 44;
